import type { StackMapDatabase } from './database.js'
import { registerInventoryApi, sendApiError } from './inventory-api.js'
import { backupApiError, registerBackupApi } from './backup-api.js'
import { SqliteInventoryRepository } from './repository.js'
import { applicationVersion } from './version.js'

export interface BuildAppOptions {
  database: StackMapDatabase
  staticRoot: string
  logger?: boolean
}

function isApiRequest(url: string): boolean {
  return url === '/api' || url.startsWith('/api/')
}

export async function buildApp(options: BuildAppOptions): Promise<FastifyInstance> {
  const app = Fastify({ logger: options.logger ?? false })
  app.setErrorHandler(async (error, request, reply) => {
    if (isApiRequest(request.url)) {
      const backupError = backupApiError(error)
      if (backupError) return reply.code(backupError.status).send({
        error: { code: backupError.code, message: backupError.message, requestId: request.id },
      })
      return sendApiError(error, request, reply)
    }
    return reply.send(error)
  })
  const inventoryRepository = new SqliteInventoryRepository(options.database.connection)

  app.addHook('onSend', async (request, reply, payload) => {
    reply.headers({
      'x-content-type-options': 'nosniff',
      'x-frame-options': 'SAMEORIGIN',
      'referrer-policy': 'strict-origin-when-cross-origin',
      'permissions-policy': 'camera=(), microphone=(), geolocation=()',
      'cache-control': request.url.startsWith('/assets/')
        ? 'public, max-age=31536000, immutable'
        : 'no-store',
    })
    return payload
  })

  app.get('/health', async (_request, reply) => {
    try {
      options.database.connection.prepare('SELECT 1').get()
      return reply.send({
        status: 'ok',
        applicationVersion,
        databaseSchemaVersion: options.database.schemaVersion(),
        datastoreAuthority: 'sqlite',
      })
    } catch {
      return reply.code(503).send({
        status: 'unavailable',
        applicationVersion,
        databaseSchemaVersion: null,
        datastoreAuthority: 'sqlite',
      })
    }
  })
  app.get('/api/v1/meta', async () => ({
    application: 'stackmap',
    datastoreAuthority: 'sqlite',
    installationId: options.database.installationId(),
    schemaVersion: options.database.schemaVersion(),
    inventoryRevision: inventoryRepository.inventoryRevision(),
  }))
  registerInventoryApi(app, inventoryRepository)
  registerBackupApi(app, inventoryRepository, options.database.installationId)

  const staticAvailable = fs.existsSync(path.join(options.staticRoot, 'index.html'))
  if (staticAvailable) {
    await app.register(fastifyStatic, { root: options.staticRoot, wildcard: false })
  }

  app.setNotFoundHandler(async (request, reply) => {
    if (isApiRequest(request.url)) {
      return reply.code(404).send({
        error: {
          code: 'API_ROUTE_NOT_FOUND',
          message: 'The requested API route was not found.',
          requestId: request.id,
        },
      })
    }
    if (staticAvailable && request.method === 'GET') return reply.sendFile('index.html')
    return reply.code(404).send({ message: 'Route not found' })
  })

  app.addHook('onClose', async () => options.database.checkpointAndClose())
  return app
}
import { useEffect, useMemo, useRef, useState } from 'react'
import './App.css'
import { serializeLegacyExport } from './data/backup'
import {
  serverBackupClient as defaultBackupClient,
  ServerBackupError,
  type RestorePreview,
  type ServerBackupClient,
} from './data/serverBackup'
import { repository as defaultRepository } from './data/httpRepository'
import {
  legacyInventoryReader as defaultLegacyReader,
  LegacyInventoryError,
  type LegacyInventoryReader,
} from './data/legacyInventory'
import type { StackMapRepository } from './data/repository'
import {
  duplicateContainerNameServiceIds,
  duplicatePortServiceIds,
  filterServices,
  getPathWarnings,
  missingServiceFields,
} from './domain/serviceUtils'
import {
  EXPOSURES,
  SERVICE_STATUSES,
  type Host,
  type Service,
  type ServiceFilters,
} from './domain/types'
import { HostManager } from './components/HostManager'
import { PathMapView } from './components/PathMapView'
import { PortMapView } from './components/PortMapView'
import { ServiceForm } from './components/ServiceForm'
import { UNASSIGNED_PATH_HOST_FILTER } from './domain/pathMap'
import { UNASSIGNED_HOST_FILTER } from './domain/portMap'

const DEFAULT_FILTERS: ServiceFilters = {
  query: '',
  status: 'all',
  hostId: 'all',
  network: 'all',
  exposure: 'all',
}

interface AppProps {
  repository?: StackMapRepository
  legacyReader?: LegacyInventoryReader
  backupClient?: ServerBackupClient
}

function App({ repository = defaultRepository, legacyReader = defaultLegacyReader, backupClient = defaultBackupClient }: AppProps) {
  const [services, setServices] = useState<Service[]>([])
  const [hosts, setHosts] = useState<Host[]>([])
  const [filters, setFilters] = useState(DEFAULT_FILTERS)
  const [editingService, setEditingService] = useState<Service | null | 'new'>(null)
  const [showHosts, setShowHosts] = useState(false)
  const [message, setMessage] = useState('')
  const [error, setError] = useState('')
  const [loading, setLoading] = useState(true)
  const [loadFailed, setLoadFailed] = useState(false)
  const [legacyBlocked, setLegacyBlocked] = useState(false)
  const [legacyDetectionFailure, setLegacyDetectionFailure] = useState<'unsupported' | 'transient' | null>(null)
  const [activeView, setActiveView] = useState<'services' | 'port-map' | 'path-map'>('services')
  const [portMapHostFilter, setPortMapHostFilter] = useState('all')
  const [pathMapHostFilter, setPathMapHostFilter] = useState('all')
  const [restoreFile, setRestoreFile] = useState<File | null>(null)
  const [restorePreview, setRestorePreview] = useState<RestorePreview | null>(null)
  const [restoreAcknowledged, setRestoreAcknowledged] = useState(false)
  const [restoreBusy, setRestoreBusy] = useState(false)
  const [showRestore, setShowRestore] = useState(false)
  const restoreStatus = useRef<HTMLDivElement>(null)
  const portMapViewButton = useRef<HTMLButtonElement>(null)
  const pathMapViewButton = useRef<HTMLButtonElement>(null)
  const returnFocusToMap = useRef<'port-map' | 'path-map' | null>(null)

  async function refresh() {
    const data = await repository.getAll()
    setServices(data.services.sort((left, right) => left.name.localeCompare(right.name)))
    setHosts(data.hosts.sort((left, right) => left.name.localeCompare(right.name)))
  }

  async function loadServerInventory() {
    setLoading(true)
    setLoadFailed(false)
    try {
      const data = await repository.getAll()
      setServices(data.services.sort((left, right) => left.name.localeCompare(right.name)))
      setHosts(data.hosts.sort((left, right) => left.name.localeCompare(right.name)))
      setError('')
      setLegacyBlocked(false)
    } catch {
      setError('StackMap could not load the server inventory. No browser fallback was used.')
      setLoadFailed(true)
    } finally {
      setLoading(false)
    }
  }

  async function retryLegacyDetection() {
    setLoading(true)
    setLoadFailed(false)
    setLegacyDetectionFailure(null)
    try {
      const hasLegacyInventory = await legacyReader.detect()
      if (hasLegacyInventory) {
        setLegacyBlocked(true)
        setLoading(false)
        return
      }
      await loadServerInventory()
    } catch (caught) {
      setError('StackMap could not safely check for legacy browser data. Server editing remains blocked.')
      setLegacyDetectionFailure(
        caught instanceof LegacyInventoryError && caught.code === 'UNSUPPORTED_ENUMERATION'
          ? 'unsupported'
          : 'transient',
      )
      setLoadFailed(true)
      setLoading(false)
    }
  }

  useEffect(() => {
    let active = true
    legacyReader.detect().then(async (hasLegacyInventory) => {
      if (!active) return
      if (hasLegacyInventory) {
        setLegacyBlocked(true)
        setLoading(false)
        return
      }
      try {
        const data = await repository.getAll()
        if (!active) return
        setServices(data.services.sort((left, right) => left.name.localeCompare(right.name)))
        setHosts(data.hosts.sort((left, right) => left.name.localeCompare(right.name)))
      } catch {
        if (!active) return
        setError('StackMap could not load the server inventory. No browser fallback was used.')
        setLoadFailed(true)
      } finally {
        if (active) setLoading(false)
      }
    }).catch((caught) => {
      if (!active) return
      setError('StackMap could not safely check for legacy browser data. Server editing remains blocked.')
      setLegacyDetectionFailure(
        caught instanceof LegacyInventoryError && caught.code === 'UNSUPPORTED_ENUMERATION'
          ? 'unsupported'
          : 'transient',
      )
      setLoadFailed(true)
      setLoading(false)
    })

    return () => {
      active = false
    }
  }, [legacyReader, repository])

  useEffect(() => {
    if (!editingService && returnFocusToMap.current) {
      const target = returnFocusToMap.current
      returnFocusToMap.current = null
      if (target === 'port-map') portMapViewButton.current?.focus()
      if (target === 'path-map') pathMapViewButton.current?.focus()
    }
  }, [editingService])

  const visibleServices = useMemo(
    () => filterServices(services, hosts, filters),
    [services, hosts, filters],
  )
  const conflictIds = useMemo(() => duplicatePortServiceIds(services), [services])
  const containerConflictIds = useMemo(
    () => duplicateContainerNameServiceIds(services),
    [services],
  )
  const networks = useMemo(
    () => [...new Set(services.map((service) => service.network).filter(Boolean))].sort(),
    [services],
  )
  const hostNames = useMemo(() => new Map(hosts.map((host) => [host.id, host.name])), [hosts])
  const dependencyNames = useMemo(
    () => new Map(services.map((service) => [service.id, service.name])),
    [services],
  )
  const effectivePortMapHostFilter =
    portMapHostFilter === 'all' ||
    portMapHostFilter === UNASSIGNED_HOST_FILTER ||
    hosts.some((host) => host.id === portMapHostFilter)
      ? portMapHostFilter
      : 'all'
  const effectivePathMapHostFilter =
    pathMapHostFilter === 'all' ||
    pathMapHostFilter === UNASSIGNED_PATH_HOST_FILTER ||
    hosts.some((host) => host.id === pathMapHostFilter)
      ? pathMapHostFilter
      : 'all'

  async function saveService(service: Service): Promise<boolean> {
    try {
      await repository.putService(service)
      await refresh()
      setEditingService(null)
      setError('')
      setMessage(`${service.name} saved.`)
      return true
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : 'The service could not be saved.')
      return false
    }
  }

  function editServiceFromPortMap(service: Service) {
    returnFocusToMap.current = 'port-map'
    setEditingService(service)
  }

  function editServiceFromPathMap(service: Service) {
    returnFocusToMap.current = 'path-map'
    setEditingService(service)
  }

  async function retireService(service: Service) {
    try {
      await repository.putService({
        ...service,
        status: 'retired',
        updatedAt: new Date().toISOString(),
      })
      await refresh()
      setError('')
      setMessage(`${service.name} retired.`)
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : 'The service could not be retired.')
    }
  }

  async function deleteService(service: Service) {
    if (!window.confirm(`Permanently delete ${service.name}? This cannot be undone.`)) return
    try {
      await repository.deleteService(service.id)
      await refresh()
      setError('')
      setMessage(`${service.name} permanently deleted.`)
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : 'The service could not be deleted.')
    }
  }

  async function saveHost(host: Host): Promise<boolean> {
    try {
      await repository.putHost(host)
      await refresh()
      setError('')
      setMessage(`${host.name} saved.`)
      return true
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : 'The host could not be saved.')
      return false
    }
  }

  async function deleteHost(host: Host) {
    if (!window.confirm(`Permanently delete host ${host.name}?`)) return
    try {
      await repository.deleteHost(host.id)
      await refresh()
      setMessage(`${host.name} deleted.`)
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : 'The host could not be deleted.')
    }
  }

  function downloadExport(serialized: string, filename: string) {
    const blob = new Blob([serialized], { type: 'application/json' })
    const url = URL.createObjectURL(blob)
    const link = document.createElement('a')
    link.href = url
    link.download = filename
    link.click()
    window.setTimeout(() => URL.revokeObjectURL(url), 0)
  }

  async function exportServerInventory() {
    try {
      const blob = await backupClient.download()
      const url = URL.createObjectURL(blob)
      const link = document.createElement('a')
      link.href = url
      link.download = `stackmap-server-backup-${new Date().toISOString().slice(0, 10)}.json`
      link.click()
      window.setTimeout(() => URL.revokeObjectURL(url), 0)
      setError('')
      setMessage('Current server-authoritative backup downloaded.')
    } catch {
      setError('The current server inventory could not be exported. Retry when the server is available.')
    }
  }

  async function previewRestore() {
    if (!restoreFile || restoreBusy) return
    setRestoreBusy(true)
    setError('')
    setMessage('Validating backup on the server…')
    try {
      const parsed: unknown = JSON.parse(await restoreFile.text())
      setRestorePreview(await backupClient.preview(parsed))
      setRestoreAcknowledged(false)
      setMessage('Backup validated. Review the summary before restoring.')
    } catch (caught) {
      setRestorePreview(null)
      setError(caught instanceof SyntaxError ? 'The selected file is not valid JSON.' : caught instanceof Error ? caught.message : 'The backup could not be previewed.')
      setMessage('')
    } finally {
      setRestoreBusy(false)
      window.setTimeout(() => restoreStatus.current?.focus(), 0)
    }
  }

  async function confirmRestore() {
    if (!restorePreview || !restoreAcknowledged || restoreBusy) return
    setRestoreBusy(true)
    setError('')
    setMessage('Replacing the current server inventory…')
    try {
      const result = await backupClient.confirm(restorePreview.previewToken, restorePreview.expectedInventoryRevision)
      await refresh()
      setRestorePreview(null)
      setRestoreFile(null)
      setRestoreAcknowledged(false)
      setMessage(`Restore complete: ${result.summary.hostCount} hosts and ${result.summary.serviceCount} services. Inventory revision ${result.inventoryRevision}.`)
    } catch (caught) {
      const requiresPreview = caught instanceof ServerBackupError &&
        ['RESTORE_PREVIEW_STALE', 'RESTORE_PREVIEW_INVALID'].includes(caught.code)
      if (requiresPreview) setRestorePreview(null)
      setError(caught instanceof Error ? caught.message : 'The restore could not be completed.')
      setMessage('')
    } finally {
      setRestoreBusy(false)
      window.setTimeout(() => restoreStatus.current?.focus(), 0)
    }
  }

  function cancelRestore() {
    setRestorePreview(null)
    setRestoreAcknowledged(false)
    setMessage('Restore cancelled. Server inventory was not changed.')
    window.setTimeout(() => restoreStatus.current?.focus(), 0)
  }

  async function exportLegacyInventory() {
    try {
      const data = await legacyReader.read()
      downloadExport(serializeLegacyExport(data), `stackmap-legacy-browser-data-${new Date().toISOString().slice(0, 10)}.json`)
      setError('')
      setMessage('Legacy browser-data backup exported. The browser data was not changed.')
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : 'Legacy browser data could not be exported.')
    }
  }

  if (loading) {
    return <div className="loading-state" role="status">Loading StackMap server inventory…</div>
  }

  if (legacyBlocked) {
    return (
      <main className="blocking-state" role="alertdialog" aria-modal="true" aria-labelledby="legacy-data-title">
        <p className="eyebrow">Legacy browser data found</p>
        <h1 id="legacy-data-title">Choose how to continue safely</h1>
        <p>Browser-local legacy hosts or services were found. This data is not stored in SQLite.</p>
        <p>The current StackMap server inventory may be empty or different. Automatic migration is not available in Task 4, and your legacy browser data will remain untouched.</p>
        {message && <div className="notice success" role="status">{message}</div>}
        {error && <div className="notice error" role="alert">{error}</div>}
        <div className="blocking-actions">
          <button className="button ghost" type="button" onClick={exportLegacyInventory} aria-label="Export legacy browser data from IndexedDB">
            Export legacy browser data
          </button>
          <button className="button primary" type="button" onClick={loadServerInventory}>
            Continue to StackMap server inventory without importing
          </button>
        </div>
        <p className="field-help">Continuing is acknowledged for this browser session only. It does not import, merge, delete, or synchronize data.</p>
      </main>
    )
  }

  if (loadFailed) {
    if (legacyDetectionFailure) {
      return (
        <main className="blocking-state" role="alert" aria-labelledby="legacy-check-error-title">
          <h1 id="legacy-check-error-title">Legacy browser-data safety check unavailable</h1>
          {legacyDetectionFailure === 'unsupported' ? (
            <>
              <p>This browser cannot safely list its legacy browser databases, so StackMap cannot determine whether older browser-local inventory exists without risking creation or modification.</p>
              <p>Use a current version of Chrome, Edge, or another Chromium-based browser for automatic safe detection.</p>
              <p>Legacy browser data might still be present. Continuing will not import or delete it, and the StackMap server inventory may be empty or different.</p>
            </>
          ) : <p>{error} This may be temporary.</p>}
          <div className="blocking-actions">
            <button className="button ghost" type="button" onClick={retryLegacyDetection}>Retry legacy browser-data check</button>
            {legacyDetectionFailure === 'unsupported' && (
              <button className="button primary" type="button" onClick={loadServerInventory}>
                Continue to server inventory; leave possible legacy data untouched
              </button>
            )}
          </div>
        </main>
      )
    }
    return (
      <main className="blocking-state" role="alert" aria-labelledby="load-error-title">
        <h1 id="load-error-title">Serve…24 tokens truncated…a = await this.database.metadata.get('schemaVersion')
    if (!metadata) {
      await this.database.metadata.put({
        key: 'schemaVersion',
        value: CURRENT_SCHEMA_VERSION,
      })
      return CURRENT_SCHEMA_VERSION
    }
    return metadata.value
  }
}

